import{_ as t,c as a,o,ah as n,ao as s,ap as p}from"./chunks/framework.Dq2_gudl.js";const b=JSON.parse('{"title":"虹の橋のむこう側 — すべての生き物と結ばれた神の契約","description":"「虹の橋」は美しい言葉ですが、聖書の虹はもっと大きい。神がすべての生き物と結ばれた永遠の契約です。","frontmatter":{"title":"虹の橋のむこう側 — すべての生き物と結ばれた神の契約","description":"「虹の橋」は美しい言葉ですが、聖書の虹はもっと大きい。神がすべての生き物と結ばれた永遠の契約です。"},"headers":[],"relativePath":"ja/pets-in-heaven/rainbow-bridge-covenant.md","filePath":"ja/pets-in-heaven/rainbow-bridge-covenant.md"}'),i={name:"ja/pets-in-heaven/rainbow-bridge-covenant.md"};function r(l,e,h,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>「みんな、あの子は虹の橋を渡ったと言います。でも、それはただのきれいな言葉なのでしょうか。それとも本当の希望なのでしょうか」</p><p class="pl-quote-soft">驚くことに、聖書には本当に虹があります。しかもその契約は、動物のために結ばれました。</p></div><section class="pl-section"><h2>1. あの虹は、動物との契約でした</h2><p>洪水のあと、神はノアと契約を結び、もう水で地を滅ぼさないと約束されました。しかしその契約の当事者は、ノアとその子孫だけではありませんでした。</p><blockquote><p><strong>創世記 9:9-13</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>「<em>すべての生き物</em>」という表現に注目してください。鳥も家畜も、地のすべての獣も、契約の当事者として名を連ねています。神は虹を雲の中に置き、<strong>ご自身と地、そしてすべての生き物との間の契約のしるし</strong>とされました。</p><p>これは聖書全体で最も見落とされ、最もやさしい事実のひとつです。<strong>神はかつて、正式に、永遠に、動物と契約を結ばれました。</strong></p><p>だから人が名づけた「虹の橋」という名前も、それほど的外れではありません。聖書はあの光がしるしだと言います。しるしは決して「終わり」を意味しません。「まだ続きがある」という意味です。</p></section><section class="pl-section"><h2>2. 来るべき世界で、彼らは安らかに伏す</h2><p>イザヤが、神が造られる世界を描くとき、その場面の中心には動物がいます。</p><blockquote><p><strong>イザヤ書 65:25</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>そしてヨハネの黙示録は、最後の礼拝で誰が歌っているのかを聞かせてくれます。</p><blockquote><p><strong>ヨハネの黙示録 5:13</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>「すべての被造物」が礼拝しています。人間だけではありません。</p><p>詩篇はこのすべてを、短い一行にまとめます。</p><blockquote><p><strong>詩篇 150:6</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>息あるものすべて — その子も — その歌の中にいます。</p></section><section class="pl-section"><h2>3. だから虹の橋のむこう側には、約束があります</h2><p>私たちが神に代わって約束を足すことはできません。しかし、神がすでに言われたことの中にとどまることはできます。すべての生き物と契約を結ばれた。造られる世界には動物が平和に暮らしている。最後の礼拝には「すべての被造物」がいる。息あるものすべてが神をほめたたえる。</p><p>これらのみことばは「あなたのその子が必ずそこにいる」とは言いません。けれど、この祈りを完全に正当なものにします。「主よ、その子があなたの約束の中にありますように。」そしてこの方は、動物のために虹まで残してくださった神です。</p><p class="pl-quote-soft">考えてみてください。神が動物のために虹を残されたのなら、あなたのその子を覚えないはずがあるでしょうか。</p></section><div class="pl-quote"><p>「あなたは雲の中に弓を置き、すべての生き物とのしるしとされました。<br>あの光を見るたび、私はその子を思い出します。<br>約束なさったとおり、その子があなたの約束の中で安らかでありますように。<br>そして恋しい日々に、あなたの契約が私を支えてくださいますように。アーメン。」</p></div><section class="pl-section"><h2>あなたのための小さな習慣</h2><p>雨のあとに虹が現れたら、それを二人のしるしにしてください。数秒そこに立って、その子に話しかけてみてください。結論は要りませんし、言葉がまとまる必要もありません。聖書の中で、あの光はいつも「契約のしるし」でした。しるしは、神が忘れていないという意味です。</p><p><a href="/ja/pets-in-heaven/">← Pets in Heaven に戻る</a> ｜ 次の記事：<a href="/ja/pets-in-heaven/permission-to-grieve">悲しんでもいいのです</a></p></section><div class="pl-cta"><h2>一緒に見た風景を残してください。</h2><p>その子の写真をメモリアルカードやポスター、短い映像に。一緒に歩いた日々が、残るかたちを持ちます。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store でダウンロード</a></div><div class="pl-bible"><h3>みことばが、これからも寄り添うように</h3><p>この記事の聖句はすべて聖書から引用しています。虹の聖書ウィジェットなら、いつでも聖書を読み、毎日の聖句ウィジェットを設定できます。会いたい日に、小さな灯りとなりますように。</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="虹の聖書ウィジェット — 2 テモテ 2:13" loading="lazy"><figcaption>ホーム画面に毎日の聖句</figcaption></figure><figure><img src="'+p+'" alt="虹の聖書 — 天国にいるペット トピック、マタイ 10:29-31" loading="lazy"><figcaption>「天国にいるペット」テーマで聖書を</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Storeで虹の聖書ウィジェットを入手</a></div>',8)])])}const f=t(i,[["render",r]]);export{b as __pageData,f as default};
